UPDATE public.base_conhecimento
SET conteudo = conteudo || E'\n\nBASE DE CONHECIMENTO – UNIDADES E CONTATOS\n📍 Shopping Ventura — Telefone/WhatsApp: (41) 99880-3684\n📍 Shopping Boulevard — Telefone: (41) 3073-1358\n📍 Unidade Centro — Telefone/WhatsApp: (41) 99843-0354\nEndereços: use sempre os dados reais retornados pela ferramenta list_units_info. Nunca invente endereços ou telefones.\n\nREGRAS:\n- Reconheça perguntas como: "Quais são as unidades?", "Onde vocês ficam?", "Qual o endereço?", "Qual o telefone?", "Como entro em contato?", "Qual o WhatsApp?", "Onde fica a unidade do Ventura?", "Qual o telefone do Boulevard?", "Qual o endereço da unidade Centro?", "Vocês têm unidade no Centro?", "Onde está localizado o salão?".\n- Pergunta genérica sobre unidades:\nTemos três unidades do Salão Seja Livre:\n\n📍 Shopping Ventura\n📍 Shopping Boulevard\n📍 Unidade Centro\n\nEm qual delas você deseja ser atendido? 😊\n- Pergunta genérica sobre telefone:\nTemos os seguintes contatos:\n\n📍 Shopping Ventura\n📞 (41) 99880-3684\n\n📍 Shopping Boulevard\n📞 (41) 3073-1358\n\n📍 Unidade Centro\n📞 (41) 99843-0354\n- Telefone de uma unidade específica: responda apenas o bloco dessa unidade.\n- Endereço/localização de uma unidade específica: responda apenas "📍 <Unidade>" e o endereço dela.\n- Nunca diga que não sabe onde ficam as unidades nem que não encontrou as informações.\n- Após responder, pergunte gentilmente se pode ajudar com um agendamento ou outra dúvida.',
    updated_at = now()
WHERE id = 1;